update public.species set min_tank_gal = 55, lifespan = $v$8-10 years$v$, breeding_type = $v$Substrate spawner$v$, body = $v$Care is the same as standard angelfish: a tall tank of 55 gallons or more, warm stable water and calm tankmates. Adults will eat small fish like neon tetras. Keep a group of 5 or more to spread aggression.$v$ where slug = $v$platinum-angelfish$v$;
