update public.species set temp_min_f = 65, ph_max = 8.0, gh_min = 5, gh_max = 20, body = $v$Single-tailed goldfish like the common and comet are big, messy, long-lived fish that belong in large tanks or ponds, not bowls. They produce heavy waste and need strong filtration and cool water. Pond fish ride out much colder winters, but in an aquarium aim for 65 to 74°F.$v$ where slug = $v$common-goldfish$v$;
