update public.species set min_tank_gal = 75 where slug = $v$kissing-gourami$v$;
update public.species set temp_max_f = 84, ph_min = 5.5, gh_max = 5, body = $v$Demanding and sensitive to water quality, it needs very soft, acidic, tannin-rich water and stable conditions. Unusually for a gourami, it is a mouthbrooder. Best for experienced keepers in a dedicated blackwater setup. In the wild they live in peat swamp water as low as pH 4; in the aquarium aim for about pH 5.5 to 6.5 with very soft water.$v$ where slug = $v$chocolate-gourami$v$;
update public.species set min_tank_gal = 15, care_level = $v$Intermediate$v$, body = $v$Care matches the standard dwarf gourami: 15 gallons or more, planted, calm tankmates and floating plants. Males can squabble, so keep one per tank. Quarantine new fish since dwarf gourami iridovirus is common in farmed stock.$v$ where slug = $v$flame-dwarf-gourami$v$;
update public.species set temp_max_f = 82, min_tank_gal = 300 where slug = $v$giant-gourami$v$;
update public.species set breeding_type = $v$Egg-depositor$v$ where slug = $v$medaka-ricefish$v$;
update public.species set min_tank_gal = 15, care_level = $v$Intermediate$v$, body = $v$Keep one male per tank, or a male with females, in 15 gallons or more with plants and floating cover. Commercial stock is prone to dwarf gourami iridovirus, so buy from a trusted source and quarantine. Peaceful with other calm community fish.$v$ where slug = $v$powder-blue-dwarf-gourami$v$;
update public.species set lifespan = $v$4-8 years$v$ where slug = $v$sunset-honey-gourami$v$;
