update public.species set ph_min = 6.0, breeding_type = $v$Egg-depositor$v$, body = $v$Pairs jump together to deposit eggs above the waterline, then the male splashes them to keep them wet. It is extraordinary behavior. Peaceful and best with a tight lid and floating plants. Keep a group of 6 or more.$v$ where slug = $v$splash-tetra$v$;
update public.species set ph_min = 6.0 where slug = $v$ornate-tetra$v$;
update public.species set ph_max = 8.0, gh_max = 20, temperament = $v$Semi-aggressive$v$, body = $v$One of the calmest medium cichlids, making it a great centerpiece for a peaceful community of similar size, though it will still eat very small fish like neon tetras. A line-bred blue form of the blue acara. Appreciates caves, sand, and the occasional flat rock for spawning.$v$ where slug = $v$electric-blue-acara$v$;
update public.species set temp_max_f = 74, min_tank_gal = 40, social = $v$Groups$v$ where slug = $v$fantail-goldfish$v$;
update public.species set temp_max_f = 74, min_tank_gal = 40, social = $v$Groups$v$ where slug = $v$oranda-goldfish$v$;
